function refreshThesisCarouselCaption(){const carousel=document.querySelector("[data-carousel]");if(!carousel)return;const index=Number(carousel.dataset.activeIndex||0),key=index===1?"thesisSlide2":"thesisSlide1",caption=carousel.querySelector("[data-carousel-caption]");if(caption){caption.dataset.i18n=key;caption.textContent=translations[document.documentElement.lang]?.[key]||translations.en[key];}}
function setLanguage(lang){const chosen=supportedLanguages.includes(lang)?lang:"en";document.documentElement.lang=chosen;document.querySelectorAll("[data-i18n]").forEach(el=>{const value=translations[chosen][el.dataset.i18n];if(value!==undefined)el.innerHTML=value;});document.querySelectorAll("[data-i18n-aria]").forEach(el=>{const value=translations[chosen][el.dataset.i18nAria];if(value!==undefined)el.setAttribute("aria-label",value);});document.querySelectorAll("[data-i18n-alt]").forEach(el=>{const value=translations[chosen][el.dataset.i18nAlt];if(value!==undefined)el.setAttribute("alt",value);});refreshThesisCarouselCaption();document.title=chosen==="es"?"Andrea Mayte Cervantes Tinco | Portafolio de ingeniería":chosen==="nl"?"Andrea Mayte Cervantes Tinco | Engineeringportfolio":"Andrea Mayte Cervantes Tinco | Engineering Portfolio";try{localStorage.setItem("portfolio-language",chosen)}catch(e){}}
langToggle.addEventListener("click",()=>{langMenu.hidden=!langMenu.hidden;langToggle.setAttribute("aria-expanded",String(!langMenu.hidden));});
langMenu.querySelectorAll("[data-lang]").forEach(b=>b.addEventListener("click",()=>{setLanguage(b.dataset.lang);langMenu.hidden=true;langToggle.setAttribute("aria-expanded","false")}));
try{setLanguage(localStorage.getItem("portfolio-language")||"en")}catch(e){setLanguage("en")}
