const modal=document.getElementById("project-modal"),closeBtn=document.getElementById("modal-close"),modalScroll=modal.querySelector(".modal-scroll"),modalImage=document.getElementById("modal-image"),modalImageCaption=document.getElementById("modal-image-caption"),galleryControls=document.getElementById("modal-gallery-controls"),galleryCount=document.getElementById("modal-gallery-count"),lightbox=document.getElementById("image-lightbox"),lightboxImage=document.getElementById("lightbox-image"),lightboxCaption=document.getElementById("lightbox-caption"),lightboxPrev=document.getElementById("lightbox-prev"),lightboxNext=document.getElementById("lightbox-next");let previousFocus=null,activeGallery=[],activeGalleryIndex=0;
function galleryCaption(item){return item.captionKey?(translations[document.documentElement.lang]?.[item.captionKey]||translations.en[item.captionKey]||""):item.caption||""}
function renderGalleryImage(){const item=activeGallery[activeGalleryIndex];if(!item)return;modalImage.src=item.src;modalImage.alt=item.alt||"Project figure";modalImageCaption.textContent=galleryCaption(item);galleryCount.textContent=`${activeGalleryIndex+1} / ${activeGallery.length}`;const multi=activeGallery.length>1;galleryControls.hidden=!multi;lightboxPrev.hidden=!multi;lightboxNext.hidden=!multi;if(!lightbox.hidden){lightboxImage.src=item.src;lightboxImage.alt=item.alt||"Project figure";lightboxCaption.textContent=galleryCaption(item)}}
function stepGallery(step){if(activeGallery.length<2)return;activeGalleryIndex=(activeGalleryIndex+step+activeGallery.length)%activeGallery.length;renderGalleryImage()}
function openProject(key){const p={...projectDetails[key],...(projectDetailTranslations[document.documentElement.lang]?.[key]||{})};if(!projectDetails[key])return;previousFocus=document.activeElement;activeGallery=p.images||[{src:p.image,alt:p.title}];activeGalleryIndex=0;modal.classList.toggle("thesis-modal",key==="thesis");document.getElementById("modal-kicker").textContent=p.kicker;document.getElementById("modal-title").textContent=p.title;document.getElementById("modal-intro").textContent=p.intro;document.getElementById("modal-context").textContent=p.context;document.getElementById("modal-approach").textContent=p.approach;document.getElementById("modal-contribution").textContent=p.contribution;document.getElementById("modal-outcome").textContent=p.outcome;document.getElementById("modal-tags").textContent=p.tags;renderGalleryImage();modal.hidden=false;document.body.classList.add("modal-open");modalScroll.scrollTop=0;closeBtn.focus()}
function closeImageViewer(){lightbox.hidden=true;document.getElementById("modal-image-zoom").focus()}
function closeProject(){if(!lightbox.hidden){closeImageViewer();return}modal.hidden=true;document.body.classList.remove("modal-open");if(previousFocus)previousFocus.focus()}
function openImageViewer(){if(!activeGallery.length)return;lightbox.hidden=false;renderGalleryImage();document.getElementById("lightbox-close").focus()}
document.addEventListener("click",e=>{const card=e.target.closest("[data-project]");if(card){e.preventDefault();openProject(card.dataset.project)}});
closeBtn.addEventListener("click",closeProject);
document.getElementById("modal-image-zoom").addEventListener("click",openImageViewer);document.getElementById("modal-gallery-prev").addEventListener("click",()=>stepGallery(-1));document.getElementById("modal-gallery-next").addEventListener("click",()=>stepGallery(1));
document.getElementById("lightbox-close").addEventListener("click",closeImageViewer);document.getElementById("lightbox-prev").addEventListener("click",()=>stepGallery(-1));document.getElementById("lightbox-next").addEventListener("click",()=>stepGallery(1));lightbox.addEventListener("click",e=>{if(e.target===lightbox)closeImageViewer()});
document.addEventListener("keydown",e=>{if(e.key==="Escape"&&!modal.hidden){closeProject();return}if(modal.hidden)return;if(e.key==="ArrowRight")stepGallery(1);if(e.key==="ArrowLeft")stepGallery(-1)});
const thesisCard=document.querySelector(".thesis-project-card");if(thesisCard)thesisCard.addEventListener("click",e=>{if(e.target.closest("button"))return;openProject("thesis")});
const menuToggle=document.getElementById("menu-toggle"),mobileNav=document.getElementById("mobile-nav");menuToggle.addEventListener("click",()=>{const open=menuToggle.getAttribute("aria-expanded")==="true";menuToggle.setAttribute("aria-expanded",String(!open));mobileNav.hidden=open;});mobileNav.querySelectorAll("a").forEach(a=>a.addEventListener("click",()=>{mobileNav.hidden=true;menuToggle.setAttribute("aria-expanded","false")}));
document.addEventListener("click",e=>{if(!langMenu.contains(e.target)&&!langToggle.contains(e.target)){langMenu.hidden=true;langToggle.setAttribute("aria-expanded","false")}});
const photos=document.querySelectorAll(".photo-carousel .hero-photo");if(photos.length>1){let current=0;window.setInterval(()=>{photos[current].classList.remove("active");current=(current+1)%photos.length;photos[current].classList.add("active")},5500)}
const thesisCarousel=document.querySelector("[data-carousel]");
if(thesisCarousel){
  const slides=[...thesisCarousel.querySelectorAll(".thesis-slide")],dots=[...thesisCarousel.querySelectorAll("[data-slide-to]")],caption=thesisCarousel.querySelector("[data-carousel-caption]");
  let activeSlide=0;
  const showThesisSlide=(index)=>{activeSlide=(index+slides.length)%slides.length;thesisCarousel.dataset.activeIndex=String(activeSlide);slides.forEach((slide,i)=>slide.classList.toggle("active",i===activeSlide));dots.forEach((dot,i)=>{dot.classList.toggle("active",i===activeSlide);dot.setAttribute("aria-pressed",String(i===activeSlide))});if(caption){const key=activeSlide===1?"thesisSlide2":"thesisSlide1";caption.dataset.i18n=key;caption.textContent=translations[document.documentElement.lang]?.[key]||translations.en[key]}};
  showThesisSlide(0);
  thesisCarousel.querySelectorAll("[data-carousel-step]").forEach(button=>button.addEventListener("click",()=>showThesisSlide(activeSlide+Number(button.dataset.carouselStep))));
  dots.forEach(dot=>dot.addEventListener("click",()=>showThesisSlide(Number(dot.dataset.slideTo))));
  if(!window.matchMedia("(prefers-reduced-motion: reduce)").matches){window.setInterval(()=>{if(!thesisCarousel.matches(":hover")&&!thesisCarousel.contains(document.activeElement))showThesisSlide(activeSlide+1)},7000)}
}
